dashboard.definition:
{
	"title": "SAP LogServ - Web Dispatcher Access",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "-30d@d,now",
				"token": "global_time"
			},
			"title": "Global Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_2nZCdB19": {
			"containerOptions": {},
			"dataSources": {
				"primary": "ds_1ZmrypYh"
			},
			"options": {
				"backgroundColor": "transparent",
				"columnGrouping": "overlay",
				"columnSpacing": 0,
				"resultLimit": 500000,
				"seriesColorsByField": {
					"Client Error (4xx)": "#dc4e41",
					"Redirect (3xx)": "#0877a6",
					"Server Error (5xx)": "#f1813f",
					"Success (2xx)": "#4fa484"
				},
				"showIndependentYRanges": true,
				"showSplitSeries": true,
				"x": "> primary | seriesByName('_time')",
				"xAxisTitleVisibility": "hide",
				"y": "> primary | frameBySeriesNames('Client Error (4xx)','Redirect (3xx)','Server Error (5xx)','Success (2xx)')",
				"y2AxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Traffic by Status Code",
			"type": "splunk.column"
		},
		"viz_8cdxDtFu": {
			"containerOptions": {},
			"dataSources": {
				"primary": "ds_yE9yBtpa"
			},
			"options": {
				"backgroundColor": "transparent",
				"yAxisScale": "log"
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Top 5 Slowest Pages",
			"type": "splunk.bar"
		},
		"viz_JQwHPBuw": {
			"options": {
				"fillColor": "transparent",
				"rx": 3,
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_Kj5JGWVb": {
			"options": {
				"fillColor": "transparent",
				"rx": 3,
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_UBrqm3dh": {
			"options": {
				"fillColor": "transparent",
				"rx": 3,
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_YIm9coVY": {
			"containerOptions": {},
			"dataSources": {
				"primary": "ds_pYyp9bI7"
			},
			"options": {
				"backgroundColor": "transparent",
				"collapseLabel": "",
				"collapseThreshold": 0,
				"showDonutHole": true
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Traffic by HTTP Method",
			"type": "splunk.pie"
		},
		"viz_aHaxUdSn": {
			"containerOptions": {},
			"dataSources": {
				"primary": "ds_TsZBieYG"
			},
			"options": {
				"backgroundColor": "transparent",
				"legendTruncation": "ellipsisMiddle",
				"seriesColorsByField": {
					"Avg Response Time (ms)": "#62b3b2"
				},
				"showRoundedY2AxisLabels": false,
				"xAxisTitleVisibility": "hide",
				"y": "> primary | frameBySeriesNames('Avg Response Time (ms)')"
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Response Time Trend",
			"type": "splunk.column"
		},
		"viz_kxbrvLhz": {
			"options": {
				"fillColor": "transparent",
				"rx": 3,
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		},
		"viz_mEe7x9fI": {
			"containerOptions": {},
			"dataSources": {
				"primary": "ds_WaZCTDkV"
			},
			"options": {
				"backgroundColor": "transparent",
				"bubbleSizeMax": 97,
				"bubbleSizeMin": 52,
				"category": "> primary | seriesByName('clientip')",
				"x": "> primary | seriesByName('requests')",
				"y": "> primary | seriesByName('unique_pages')"
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Top Client IPs by Traffic",
			"type": "splunk.bubble"
		},
		"viz_yfcE62rT": {
			"options": {
				"fillColor": "transparent",
				"rx": 3,
				"strokeColor": "#0877a6"
			},
			"type": "splunk.rectangle"
		}
	},
	"dataSources": {
		"ds_1ZmrypYh": {
			"name": "Column chart search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=sap_webdispatcher_access\r\n| eval status_group = case(\r\n    tonumber(status) < 300, \"Success (2xx)\",\r\n    tonumber(status) < 400, \"Redirect (3xx)\", \r\n    tonumber(status) < 500, \"Client Error (4xx)\",\r\n    tonumber(status) >= 500, \"Server Error (5xx)\",\r\n    1=1, \"Other\"\r\n)\r\n| timechart span=1h count by status_group",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_F7WLfuRN_ds_yE9yBtpa": {
			"name": "Bubble chart search copy 1",
			"options": {
				"query": "index=\"sap_logserv_logs\" tag=dns message_type=\"QUERY\"\r\n| fields _time, query\r\n| streamstats current=f last(_time) as last_time by query\r\n| eval gap=last_time - _time\r\n| stats count avg(gap) AS AverageBeaconTime var(gap) AS VarianceBeaconTime BY query\r\n| eval AverageBeaconTime=round(AverageBeaconTime,3), VarianceBeaconTime=round(VarianceBeaconTime,3)\r\n| sort -count\r\n| where VarianceBeaconTime < 60 AND count > 2 AND AverageBeaconTime>1.000\r\n| table  query VarianceBeaconTime  count AverageBeaconTime",
				"queryParameters": {
					"earliest": "1751371200",
					"latest": "1751479200"
				}
			},
			"type": "ds.search"
		},
		"ds_TsZBieYG": {
			"name": "Scatter chart search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=sap_webdispatcher_access\r\n| eval response_time_ms = tonumber(total_us)/1000\r\n| timechart span=1h avg(response_time_ms) as \"Avg Response Time (ms)\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_WaZCTDkV": {
			"name": "Bubble chart search 2",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=sap_webdispatcher_access \r\n| stats count as requests, dc(uri) as unique_pages, avg(tonumber(total_us)/1000) as avg_response_ms by clientip\r\n| sort -requests\r\n| head 25\r\n| table clientip, requests, unique_pages",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_pYyp9bI7": {
			"name": "Requests by Record Type search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=sap_webdispatcher_access\r\n| stats count by method\r\n| sort -count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_yE9yBtpa": {
			"name": "Bubble chart search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=sap_webdispatcher_access \r\n| eval response_time_ms = tonumber(total_us)/1000\r\n| stats avg(response_time_ms) as avg_response, count as requests by uri\r\n| eval avg_response = round(avg_response, 1)\r\n| sort -avg_response\r\n| head 5\r\n| table uri, avg_response, requests",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
	"layout": {
		"globalInputs": [
			"input_global_trp"
		],
		"layoutDefinitions": {
			"layout_1": {
				"options": {
					"display": "auto",
					"height": 960,
					"width": 1920
				},
				"structure": [
					{
						"item": "viz_UBrqm3dh",
						"position": {
							"h": 410,
							"w": 1210,
							"x": 710,
							"y": 320
						},
						"type": "block"
